  ("tools/formatter/document_json.brp", "import:\n\t./document_layout:\n\t\tDoc(\n\t\t\tNil,\n\t\t\tText,\n\t\t\tHardline,\n\t\t\tSoftline,\n\t\t\tSoftlineSpace,\n\t\t\tIndent,\n\t\t\tGroup,\n\t\t\tConcat,\n\t\t\tIfBreak,\n\t\t\tLineSuffix,\n\t\t),\n\t\tlayout,\n\t./json_fields: field, int_field, string_field\n\tjson: JsonValue, parse_json\n\n\nprivate pure func document_field(value: JsonValue, key: String) -> Result[Doc, String]:\n\tchild ?= value.field(key)\n\tchild.document_from_json()\n\n\npure func document_from_json(value: JsonValue) -> Result[Doc, String]:\n\ttag ?= value.string_field(\"tag\")\n\n\tmatch tag:\n\t\t\"Nil\":\n\t\t\tOk(Nil)\n\t\t\"Text\":\n\t\t\ts ?= value.string_field(\"text\")\n\t\t\tOk(Text(s))\n\t\t\"Hardline\":\n\t\t\tOk(Hardline)\n\t\t\"Softline\":\n\t\t\tOk(Softline)\n\t\t\"SoftlineSpace\":\n\t\t\tOk(SoftlineSpace)\n\t\t\"Indent\":\n\t\t\twidth ?= value.int_field(\"width\")\n\t\t\tdoc ?= value.document_field(\"doc\")\n\t\t\tOk(Indent(width, doc))\n\t\t\"Group\":\n\t\t\tdoc ?= value.document_field(\"doc\")\n\t\t\tOk(Group(doc))\n\t\t\"Concat\":\n\t\t\tleft ?= value.document_field(\"left\")\n\t\t\tright ?= value.document_field(\"right\")\n\t\t\tOk(Concat(left, right))\n\t\t\"IfBreak\":\n\t\t\tbroken ?= value.document_field(\"broken\")\n\t\t\tflat ?= value.document_field(\"flat\")\n\t\t\tOk(IfBreak(broken, flat))\n\t\t\"LineSuffix\":\n\t\t\ts ?= value.string_field(\"text\")\n\t\t\tOk(LineSuffix(s))\n\t\t_:\n\t\t\tErr(\"unknown Doc JSON tag: \" + tag)\n\n\npure func document_from_json_string(input: String) -> Result[Doc, String]:\n\tvalue ?= input.parse_json()\n\tvalue.document_from_json()\n\n\npure func render_document_json(width: Int, input: String) -> Result[String, String]:\n\tdoc ?= input.document_from_json_string()\n\tOk(width.layout(doc))\n");
  ("tools/formatter/document_layout.brp", "-- Formatter document IR and layout engine.\n-- Blorp owns the formatter document algebra and layout phase; OCaml only\n-- projects parsed source into formatter JSON.\nunion Doc:\n\tNil\n\tText(String)\n\tHardline\n\tSoftline\n\tSoftlineSpace\n\tIndent(Int, Doc)\n\tGroup(Doc)\n\tConcat(Doc, Doc)\n\tIfBreak(Doc, Doc)\n\tLineSuffix(String)\n\n\nunion LayoutMode:\n\tFlatMode\n\tBreakMode\n\n\nrecord Command {\n\tindent: Int,\n\tmode: LayoutMode,\n\tdocument: Doc\n}\n\n\nrecord RenderState {\n\toutput: String,\n\tcolumn: Int,\n\tsuffixes: List[String]\n}\n\n\nLINE_WIDTH: Int = 100\n\n\npure func command(indent: Int, mode: LayoutMode, document: Doc) -> Command:\n\t{\n\t\tindent = indent,\n\t\tmode = mode,\n\t\tdocument = document\n\t}\n\n\npure func render_state(output: String, column: Int, suffixes: List[String]) -> RenderState:\n\t{\n\t\toutput = output,\n\t\tcolumn = column,\n\t\tsuffixes = suffixes\n\t}\n\n\npure func text(source: String) -> Doc:\n\tif source == \"\":\n\t\tNil\n\telse:\n\t\tText(source)\n\n\nnil: Doc = Nil\n\nhardline: Doc = Hardline\n\nsoftline: Doc = Softline\n\nsoftline_space: Doc = SoftlineSpace\n\n\npure func nest(width: Int, document: Doc) -> Doc:\n\tIndent(width, document)\n\n\npure func if_break(broken_document: Doc, flat_document: Doc) -> Doc:\n\tIfBreak(broken_document, flat_document)\n\n\npure func cat(a: Doc, b: Doc) -> Doc:\n\tmatch a:\n\t\tNil:\n\t\t\tb\n\t\t_:\n\t\t\tmatch b:\n\t\t\t\tNil:\n\t\t\t\t\ta\n\t\t\t\t_:\n\t\t\t\t\tConcat(a, b)\n\n\npure func concat_documents(documents: List[Doc]) -> Doc:\n\tvar result: Doc = Nil\n\n\tfor document in documents:\n\t\tresult = result.cat(document)\n\n\tresult\n\n\npure func indent(document: Doc) -> Doc:\n\t4.nest(document)\n\n\npure func group(document: Doc) -> Doc:\n\tGroup(document)\n\n\npure func line_suffix(source: String) -> Doc:\n\tLineSuffix(source)\n\n\npure func intersperse(separator: Doc, documents: List[Doc]) -> Doc:\n\tmatch documents:\n\t\t[]:\n\t\t\tNil\n\t\t[x]:\n\t\t\tx\n\t\t[x, ...rest]:\n\t\t\tx\n\t\t\t\t.cat(separator)\n\t\t\t\t.cat(separator.intersperse(rest))\n\n\npure func comma_sep(documents: List[Doc]) -> Doc:\n\ttext(\", \").intersperse(documents)\n\n\npure func comma_sep_break(documents: List[Doc]) -> Doc:\n\tmatch documents:\n\t\t[]:\n\t\t\tNil\n\t\t[x]:\n\t\t\tx.cat(text(\",\").if_break(Nil))\n\t\t[x, ...rest]:\n\t\t\tx\n\t\t\t\t.cat(text(\",\"))\n\t\t\t\t.cat(SoftlineSpace.cat(rest.comma_sep_break()))\n\n\npure func comma_hardline_documents(documents: List[Doc]) -> Doc:\n\tmatch documents:\n\t\t[]:\n\t\t\tNil\n\t\t[x]:\n\t\t\tx\n\t\t[x, ...rest]:\n\t\t\tx\n\t\t\t\t.cat(text(\",\"))\n\t\t\t\t.cat(hardline)\n\t\t\t\t.cat(rest.comma_hardline_documents())\n\n\npure func hardlines(documents: List[Doc]) -> Doc:\n\tHardline.intersperse(documents)\n\n\npure func blank_lines(count: Int, documents: List[Doc]) -> Doc:\n\tvar separator: Doc = Nil\n\n\tfor _ in 0..count + 1:\n\t\tseparator = separator.cat(Hardline)\n\n\tseparator.intersperse(documents)\n\n\npure func surround(left: String, right: String, document: Doc) -> Doc:\n\tleft\n\t\t.text()\n\t\t.cat(document.cat(right.text()))\n\n\npure func parens(document: Doc) -> Doc:\n\tsurround(\"(\", \")\", document)\n\n\npure func push1(command_value: Command, rest: List[Command]) -> List[Command]:\n\t[command_value].concat(rest)\n\n\npure func push2(first: Command, second: Command, rest: List[Command]) -> List[Command]:\n\t[first, second].concat(rest)\n\n\npure func fits(remaining: Int, work: List[Command]) -> Bool:\n\tvar current_remaining: Int = remaining\n\tvar current_work: List[Command] = work\n\tvar done: Bool = False\n\tvar result: Bool = False\n\n\twhile not done:\n\t\tif current_remaining < 0:\n\t\t\tresult = False\n\t\t\tdone = True\n\t\telse:\n\t\t\tmatch current_work:\n\t\t\t\t[]:\n\t\t\t\t\tresult = True\n\t\t\t\t\tdone = True\n\t\t\t\t[command_value, ...rest]:\n\t\t\t\t\tmatch command_value.document:\n\t\t\t\t\t\tNil:\n\t\t\t\t\t\t\tcurrent_work = rest\n\t\t\t\t\t\tText(source):\n\t\t\t\t\t\t\tcurrent_remaining -= source.length()\n\t\t\t\t\t\t\tcurrent_work = rest\n\t\t\t\t\t\tHardline:\n\t\t\t\t\t\t\tresult = True\n\t\t\t\t\t\t\tdone = True\n\t\t\t\t\t\tSoftline:\n\t\t\t\t\t\t\tcurrent_work = command(command_value.indent, FlatMode, Nil).push1(rest)\n\t\t\t\t\t\tSoftlineSpace:\n\t\t\t\t\t\t\tmatch command_value.mode:\n\t\t\t\t\t\t\t\tFlatMode:\n\t\t\t\t\t\t\t\t\tcurrent_remaining -= 1\n\t\t\t\t\t\t\t\t\tcurrent_work = rest\n\t\t\t\t\t\t\t\tBreakMode:\n\t\t\t\t\t\t\t\t\tresult = True\n\t\t\t\t\t\t\t\t\tdone = True\n\t\t\t\t\t\tIndent(extra, inner):\n\t\t\t\t\t\t\tcurrent_work = command(\n\t\t\t\t\t\t\t\tcommand_value.indent + extra,\n\t\t\t\t\t\t\t\tcommand_value.mode,\n\t\t\t\t\t\t\t\tinner,\n\t\t\t\t\t\t\t).push1(rest)\n\t\t\t\t\t\tGroup(inner):\n\t\t\t\t\t\t\tcurrent_work = command(\n\t\t\t\t\t\t\t\tcommand_value.indent,\n\t\t\t\t\t\t\t\tFlatMode,\n\t\t\t\t\t\t\t\tinner,\n\t\t\t\t\t\t\t).push1(rest)\n\t\t\t\t\t\tConcat(a, b):\n\t\t\t\t\t\t\tcurrent_work = command(\n\t\t\t\t\t\t\t\tcommand_value.indent,\n\t\t\t\t\t\t\t\tcommand_value.mode,\n\t\t\t\t\t\t\t\ta,\n\t\t\t\t\t\t\t).push2(\n\t\t\t\t\t\t\t\tcommand(command_value.indent, command_value.mode, b),\n\t\t\t\t\t\t\t\trest,\n\t\t\t\t\t\t\t)\n\t\t\t\t\t\tIfBreak(broken_document, flat_document):\n\t\t\t\t\t\t\tmatch command_value.mode:\n\t\t\t\t\t\t\t\tFlatMode:\n\t\t\t\t\t\t\t\t\tcurrent_work = command(\n\t\t\t\t\t\t\t\t\t\tcommand_value.indent,\n\t\t\t\t\t\t\t\t\t\tFlatMode,\n\t\t\t\t\t\t\t\t\t\tflat_document,\n\t\t\t\t\t\t\t\t\t).push1(rest)\n\t\t\t\t\t\t\t\tBreakMode:\n\t\t\t\t\t\t\t\t\tcurrent_work = command(\n\t\t\t\t\t\t\t\t\t\tcommand_value.indent,\n\t\t\t\t\t\t\t\t\t\tBreakMode,\n\t\t\t\t\t\t\t\t\t\tbroken_document,\n\t\t\t\t\t\t\t\t\t).push1(rest)\n\t\t\t\t\t\tLineSuffix(_):\n\t\t\t\t\t\t\tcurrent_work = rest\n\n\tresult\n\n\npure func flush_line_suffixes(state: RenderState) -> RenderState:\n\tif state.suffixes.length() == 0:\n\t\tstate\n\telse:\n\t\trender_state(state.output + state.suffixes.join(\"\"), state.column, [])\n\n\npure func emit_newline(state: RenderState, indent_width: Int) -> RenderState:\n\tflushed: RenderState = state.flush_line_suffixes()\n\ttabs: Int = indent_width / 4\n\n\tprefix: String = if tabs > 0:\n\t\t\"\\t\".repeat(tabs)\n\telse:\n\t\t\"\"\n\n\trender_state(flushed.output + \"\\n\" + prefix, indent_width, [])\n\n\npure func enqueue_line_suffix(state: RenderState, suffix: String) -> RenderState:\n\trender_state(\n\t\tstate.output,\n\t\tstate.column,\n\t\tstate.suffixes.append(\" \" + suffix),\n\t)\n\n\npure func render_loop(width: Int, state: RenderState, work: List[Command]) -> RenderState:\n\tvar current_state: RenderState = state\n\tvar current_work: List[Command] = work\n\tvar done: Bool = False\n\n\twhile not done:\n\t\tmatch current_work:\n\t\t\t[]:\n\t\t\t\tcurrent_state = current_state.flush_line_suffixes()\n\t\t\t\tdone = True\n\t\t\t[command_value, ...rest]:\n\t\t\t\tmatch command_value.document:\n\t\t\t\t\tNil:\n\t\t\t\t\t\tcurrent_work = rest\n\t\t\t\t\tText(source):\n\t\t\t\t\t\tcurrent_state = render_state(\n\t\t\t\t\t\t\tcurrent_state.output + source,\n\t\t\t\t\t\t\tcurrent_state.column + source.length(),\n\t\t\t\t\t\t\tcurrent_state.suffixes,\n\t\t\t\t\t\t)\n\t\t\t\t\t\tcurrent_work = rest\n\t\t\t\t\tHardline:\n\t\t\t\t\t\tcurrent_state = current_state.emit_newline(command_value.indent)\n\t\t\t\t\t\tcurrent_work = rest\n\t\t\t\t\tSoftline:\n\t\t\t\t\t\tmatch command_value.mode:\n\t\t\t\t\t\t\tFlatMode:\n\t\t\t\t\t\t\t\tcurrent_work = rest\n\t\t\t\t\t\t\tBreakMode:\n\t\t\t\t\t\t\t\tcurrent_state = current_state.emit_newline(command_value.indent)\n\t\t\t\t\t\t\t\tcurrent_work = rest\n\t\t\t\t\tSoftlineSpace:\n\t\t\t\t\t\tmatch command_value.mode:\n\t\t\t\t\t\t\tFlatMode:\n\t\t\t\t\t\t\t\tcurrent_state = render_state(\n\t\t\t\t\t\t\t\t\tcurrent_state.output + \" \",\n\t\t\t\t\t\t\t\t\tcurrent_state.column + 1,\n\t\t\t\t\t\t\t\t\tcurrent_state.suffixes,\n\t\t\t\t\t\t\t\t)\n\t\t\t\t\t\t\t\tcurrent_work = rest\n\t\t\t\t\t\t\tBreakMode:\n\t\t\t\t\t\t\t\tcurrent_state = current_state.emit_newline(command_value.indent)\n\t\t\t\t\t\t\t\tcurrent_work = rest\n\t\t\t\t\tIndent(extra, inner):\n\t\t\t\t\t\tcurrent_work = command(\n\t\t\t\t\t\t\tcommand_value.indent + extra,\n\t\t\t\t\t\t\tcommand_value.mode,\n\t\t\t\t\t\t\tinner,\n\t\t\t\t\t\t).push1(rest)\n\t\t\t\t\tGroup(inner):\n\t\t\t\t\t\tflat_command: Command = command(command_value.indent, FlatMode, inner)\n\n\t\t\t\t\t\tif (width - current_state.column).fits(flat_command.push1(rest)):\n\t\t\t\t\t\t\tcurrent_work = flat_command.push1(rest)\n\t\t\t\t\t\telse:\n\t\t\t\t\t\t\tcurrent_work = command(\n\t\t\t\t\t\t\t\tcommand_value.indent,\n\t\t\t\t\t\t\t\tBreakMode,\n\t\t\t\t\t\t\t\tinner,\n\t\t\t\t\t\t\t).push1(rest)\n\t\t\t\t\tConcat(a, b):\n\t\t\t\t\t\tcurrent_work = command(command_value.indent, command_value.mode, a).push2(\n\t\t\t\t\t\t\tcommand(command_value.indent, command_value.mode, b),\n\t\t\t\t\t\t\trest,\n\t\t\t\t\t\t)\n\t\t\t\t\tIfBreak(broken_document, flat_document):\n\t\t\t\t\t\tmatch command_value.mode:\n\t\t\t\t\t\t\tFlatMode:\n\t\t\t\t\t\t\t\tcurrent_work = command(\n\t\t\t\t\t\t\t\t\tcommand_value.indent,\n\t\t\t\t\t\t\t\t\tFlatMode,\n\t\t\t\t\t\t\t\t\tflat_document,\n\t\t\t\t\t\t\t\t).push1(rest)\n\t\t\t\t\t\t\tBreakMode:\n\t\t\t\t\t\t\t\tcurrent_work = command(\n\t\t\t\t\t\t\t\t\tcommand_value.indent,\n\t\t\t\t\t\t\t\t\tBreakMode,\n\t\t\t\t\t\t\t\t\tbroken_document,\n\t\t\t\t\t\t\t\t).push1(rest)\n\t\t\t\t\tLineSuffix(source):\n\t\t\t\t\t\tcurrent_state = current_state.enqueue_line_suffix(source)\n\t\t\t\t\t\tcurrent_work = rest\n\n\tcurrent_state\n\n\npure func render(width: Int, document: Doc) -> String:\n\trendered: RenderState = render_loop(\n\t\twidth,\n\t\trender_state(\"\", 0, []),\n\t\t[command(0, BreakMode, document)],\n\t)\n\trendered.output\n\n\npure func collapse_blank_lines(\n\tlines: List[String],\n\tblank_count: Int,\n\tacc: List[String],\n) -> List[String]:\n\tmatch lines:\n\t\t[]:\n\t\t\tacc.reverse()\n\t\t[line, ...rest]:\n\t\t\tif line == \"\":\n\t\t\t\tif blank_count < 2:\n\t\t\t\t\trest.collapse_blank_lines(\n\t\t\t\t\t\tblank_count + 1,\n\t\t\t\t\t\t[line].concat(acc),\n\t\t\t\t\t)\n\t\t\t\telse:\n\t\t\t\t\trest.collapse_blank_lines(blank_count, acc)\n\t\t\telse:\n\t\t\t\trest.collapse_blank_lines(\n\t\t\t\t\t0,\n\t\t\t\t\t[line].concat(acc),\n\t\t\t\t)\n\n\npure func drop_trailing_blanks(lines: List[String]) -> List[String]:\n\tmatch lines:\n\t\t[]:\n\t\t\t[]\n\t\t[line, ...rest]:\n\t\t\ttail: List[String] = rest.drop_trailing_blanks()\n\n\t\t\tif tail.length() == 0 and line == \"\":\n\t\t\t\t[]\n\t\t\telse:\n\t\t\t\t[line].concat(tail)\n\n\npure func post_process(source: String) -> String:\n\tvar trimmed: List[String] = []\n\n\tfor line in source.split(\"\\n\"):\n\t\ttrimmed = trimmed.append(line.trim_right())\n\n\tcollapsed: List[String] = trimmed.collapse_blank_lines(0, [])\n\tbody: List[String] = collapsed.drop_trailing_blanks()\n\n\tif body.length() == 0:\n\t\t\"\"\n\telse:\n\t\tbody.join(\"\\n\") + \"\\n\"\n\n\npure func layout(width: Int, document: Doc) -> String:\n\twidth\n\t\t.render(document)\n\t\t.post_process()\n\n\npure func layout_default(document: Doc) -> String:\n\tLINE_WIDTH.layout(document)\n");
  ("tools/formatter/expression_documents.brp", "import:\n\t./document_layout:\n\t\tDoc,\n\t\tcomma_hardline_documents,\n\t\tcomma_sep,\n\t\tcomma_sep_break,\n\t\tconcat_documents,\n\t\thardline,\n\t\thardlines,\n\t\tlayout,\n\t\tline_suffix,\n\t\tsoftline,\n\t\tsoftline_space,\n\t\ttext,\n\t./json_fields: array_field, bool_field, field, int_field, parsed_array_field, string_field\n\t./type_documents:\n\t\tTypeConstraint,\n\t\tTypeExpression,\n\t\ttype_constraint_array_field_or_empty,\n\t\ttype_constraint_documents,\n\t\ttype_expression_from_json,\n\tjson: JsonValue, parse_json\n\n\nrecord StringFlags {\n\traw: Bool,\n\tmultiline: Bool\n}\n\n\nunion Literal:\n\tIntLiteral(String)\n\tInt128Literal(String)\n\tFloatLiteral(String)\n\tStringLiteral(String, StringFlags)\n\tBoolLiteral(Bool)\n\tCharLiteral(Int)\n\n\nunion UnaryOp:\n\tNegOp\n\tNotOp\n\n\nunion BinaryOp:\n\tAddOp\n\tSubOp\n\tMulOp\n\tDivOp\n\tModOp\n\tLtOp\n\tGtOp\n\tLeOp\n\tGeOp\n\tEqOp\n\tNeOp\n\n\nunion LogicalOp:\n\tAndOp\n\tOrOp\n\n\nunion Pattern:\n\tWildcardPattern\n\tVarPattern(String)\n\tConstructorPattern(String, List[Pattern])\n\tLiteralPattern(Literal)\n\tTuplePattern(List[Pattern])\n\tQualifiedPattern(String, String, List[Pattern])\n\tListPattern(List[Pattern])\n\tListSpreadPattern(List[Pattern], Pattern)\n\tOrPattern(List[Pattern])\n\n\nunion FunctionParameter:\n\tNameParam(String)\n\tTypedNameParam(String, TypeExpression)\n\tPatternParam(Pattern)\n\tTypedPatternParam(Pattern, TypeExpression)\n\n\nunion StringInterpolationPart:\n\tStringInterpolationTextPart(String)\n\tStringInterpolationExpressionPart(Expression)\n\n\nunion BlockItem:\n\tBlockCommentItem(Bool, String)\n\tBlockExpressionItem(Bool, Expression, Option[String])\n\n\nunion MatchCase:\n\tMatchCaseData(Pattern, Expression, Option[String])\n\n\nunion SelectArm:\n\tSelectRecvArm(String, Expression, Expression)\n\tSelectAfterArm(Expression, Expression)\n\tSelectSealedArm(Expression, Expression)\n\n\nunion Expression:\n\tIdentifierExpression(String)\n\tLiteralExpression(Literal)\n\tVoidExpression\n\tBreakExpression\n\tContinueExpression\n\tBuiltinExpression\n\tBuiltinRuntimeExpression(String)\n\tFieldAccessExpression(Expression, String)\n\tCallExpression(Expression, List[Expression])\n\tOpaqueIntoExpression(TypeExpression, Expression)\n\tOpaqueFromExpression(TypeExpression, Expression)\n\tUnaryExpression(UnaryOp, Expression)\n\tBinaryExpression(BinaryOp, Expression, Expression)\n\tLogicalExpression(LogicalOp, Expression, Expression)\n\tTupleExpression(List[Expression])\n\tListExpression(List[Expression])\n\tVectorExpression(List[Expression])\n\tRecordExpression(List[(String, Expression)])\n\tRecordUpdateExpression(Expression, List[(String, Expression)])\n\tAscriptionExpression(Expression, TypeExpression)\n\tRangeExpression(Expression, Expression)\n\tSubscriptExpression(Expression, Expression)\n\tMultiSubscriptExpression(Expression, List[Expression])\n\tDictionaryExpression(List[(Expression, Expression)])\n\tAssignmentExpression(String, Expression)\n\tCompoundAssignmentExpression(String, BinaryOp, Expression)\n\tVariableDeclarationExpression(String, Bool, Expression)\n\tTypedVariableDeclarationExpression(String, Bool, TypeExpression, Expression)\n\tTupleDestructureExpression(List[String], Expression)\n\tSubscriptAssignmentExpression(Expression, List[Expression], Expression)\n\tQuestionBindExpression(String, Expression)\n\tTypedQuestionBindExpression(String, TypeExpression, Expression)\n\tBlockExpression(List[Expression])\n\tSpacedBlockExpression(List[(Bool, Expression)])\n\tItemBlockExpression(List[BlockItem])\n\tIfExpression(Expression, Expression)\n\tIfElseExpression(Expression, Expression, Expression)\n\tMatchExpression(Expression, List[MatchCase])\n\tSelectExpression(List[SelectArm])\n\tWhileExpression(Expression, Expression)\n\tForExpression(String, Expression, Expression)\n\tTupleForExpression(List[String], Expression, Expression)\n\tLambdaExpression(Bool, List[FunctionParameter], Expression)\n\tTypedLambdaExpression(Bool, List[FunctionParameter], TypeExpression, Expression)\n\tFunctionDeclarationExpression(String, Bool, List[String], List[FunctionParameter], List[TypeConstraint], Expression)\n\tTypedFunctionDeclarationExpression(String, Bool, List[String], List[FunctionParameter], TypeExpression, List[TypeConstraint], Expression)\n\tStringInterpolationExpression(List[StringInterpolationPart], Bool)\n\tDebugBlockExpression(Expression)\n\tConcurrentExpression(List[Expression], Option[Expression], Option[Int])\n\tConcurrentBindExpression(String, Option[TypeExpression], Expression)\n\tDetachExpression(Expression)\n\tConcurrentlyLoopExpression(String, Expression, Expression, Option[Expression], ConcurrentlyLoopWidth)\n\tWithExpression(String, Option[TypeExpression], Bool, Expression, Option[String], Option[Expression], Expression)\n\n\nunion ConcurrentlyLoopWidth:\n\tConcurrentlyLoopLimit(Int)\n\n\nrecord UfcsStep {\n\tname: String,\n\targs: List[Expression]\n}\n\n\nrecord UfcsChain {\n\treceiver: Expression,\n\tsteps: List[UfcsStep]\n}\n\n\nprivate pure func hex_digit(n: Int) -> String:\n\tif n < 10:\n\t\tto_char(to_int('0') + n).to_string()\n\telse:\n\t\tto_char(to_int('A') + n - 10).to_string()\n\n\nprivate pure func hex_upper(n: Int) -> String:\n\tif n == 0:\n\t\t\"0\"\n\telse:\n\t\tvar value: Int = n\n\t\tvar output: String = \"\"\n\n\t\twhile value > 0:\n\t\t\tdigit: Int = value % 16\n\t\t\toutput = digit.hex_digit() + output\n\t\t\tvalue /= 16\n\n\t\toutput\n\n\nprivate pure func unicode_escape(code: Int) -> String:\n\t\"\\\\u{\" + code.hex_upper() + \"}\"\n\n\nprivate pure func escape_char_code(code: Int, escape_single_quote: Bool) -> String:\n\tif code == 10:\n\t\t\"\\\\n\"\n\telse if code == 9:\n\t\t\"\\\\t\"\n\telse if code == 13:\n\t\t\"\\\\r\"\n\telse if code == 92:\n\t\t\"\\\\\\\\\"\n\telse if code == 34:\n\t\t\"\\\\\\\"\"\n\telse if code == 39 and escape_single_quote:\n\t\t\"\\\\'\"\n\telse if code == 0:\n\t\t\"\\\\0\"\n\telse if code >= 32 and code < 127:\n\t\tto_char(code).to_string()\n\telse:\n\t\tcode.unicode_escape()\n\n\npure func escape_string_value(s: String) -> String:\n\tvar output: String = \"\"\n\tvar i: Int = 0\n\n\twhile i < s.length():\n\t\tmatch s.get(i):\n\t\t\tSome(c):\n\t\t\t\tcode: Int = c.to_int()\n\n\t\t\t\tif code >= 128:\n\t\t\t\t\toutput += s.substring(i, 1)\n\t\t\t\telse:\n\t\t\t\t\toutput += escape_char_code(code, False)\n\t\t\tNone:\n\t\t\t\tvoid\n\n\t\ti += 1\n\n\toutput\n\n\nprivate pure func escape_multiline_string_value(s: String) -> String:\n\tvar output: String = \"\"\n\tvar i: Int = 0\n\n\twhile i < s.length():\n\t\tmatch s.get(i):\n\t\t\tSome(c):\n\t\t\t\tcode: Int = c.to_int()\n\n\t\t\t\tif code >= 128:\n\t\t\t\t\toutput += s.substring(i, 1)\n\t\t\t\telse if code == 92:\n\t\t\t\t\toutput += \"\\\\\\\\\"\n\t\t\t\telse if code == 9:\n\t\t\t\t\toutput += \"\\\\t\"\n\t\t\t\telse if code == 13:\n\t\t\t\t\toutput += \"\\\\r\"\n\t\t\t\telse if code == 0:\n\t\t\t\t\toutput += \"\\\\0\"\n\t\t\t\telse:\n\t\t\t\t\toutput += c.to_string()\n\t\t\tNone:\n\t\t\t\tvoid\n\n\t\ti += 1\n\n\toutput\n\n\nprivate pure func pipe_string_line_document(line: String) -> Doc:\n\t(\"|\" + line).text()\n\n\nprivate pure func pipe_string_line_documents(lines: List[String]) -> List[Doc]:\n\tvar documents: List[Doc] = []\n\n\tfor line in lines:\n\t\tdocuments = documents.append(line.pipe_string_line_document())\n\n\tdocuments\n\n\nprivate pure func pipe_string_content_document(value: String) -> Doc:\n\tvalue\n\t\t.split(\"\\n\")\n\t\t.pipe_string_line_documents()\n\t\t.hardlines()\n\n\nprivate pure func pipe_string_literal_document(value: String, raw: Bool) -> Doc:\n\tif raw:\n\t\t\"raw\"\n\t\t\t.text()\n\t\t\t.cat(\n\t\t\t\thardline\n\t\t\t\t\t.cat(value.pipe_string_content_document())\n\t\t\t\t\t.indent(),\n\t\t\t)\n\telse:\n\t\tvalue.pipe_string_content_document()\n\n\nprivate pure func is_pipe_string_expression(expr: Expression) -> Bool:\n\tmatch expr:\n\t\tLiteralExpression(StringLiteral(_, flags)):\n\t\t\tflags.multiline\n\t\tStringInterpolationExpression(_, is_multiline):\n\t\t\tis_multiline\n\t\t_:\n\t\t\tFalse\n\n\npure func assignment_value_document(operator_text: String, value: Expression) -> Doc:\n\tif value.is_pipe_string_expression():\n\t\tmatch value:\n\t\t\tLiteralExpression(StringLiteral(_, flags)):\n\t\t\t\tif flags.raw:\n\t\t\t\t\toperator_text\n\t\t\t\t\t\t.text()\n\t\t\t\t\t\t.cat(\" \".text())\n\t\t\t\t\t\t.cat(value.expression_document())\n\t\t\t\telse:\n\t\t\t\t\toperator_text\n\t\t\t\t\t\t.text()\n\t\t\t\t\t\t.cat(\n\t\t\t\t\t\t\thardline\n\t\t\t\t\t\t\t\t.cat(value.expression_document())\n\t\t\t\t\t\t\t\t.indent(),\n\t\t\t\t\t\t)\n\t\t\tStringInterpolationExpression(_, _):\n\t\t\t\toperator_text\n\t\t\t\t\t.text()\n\t\t\t\t\t.cat(\n\t\t\t\t\t\thardline\n\t\t\t\t\t\t\t.cat(value.expression_document())\n\t\t\t\t\t\t\t.indent(),\n\t\t\t\t\t)\n\t\t\t_:\n\t\t\t\toperator_text\n\t\t\t\t\t.text()\n\t\t\t\t\t.cat(\" \".text())\n\t\t\t\t\t.cat(value.expression_document())\n\telse:\n\t\toperator_text\n\t\t\t.text()\n\t\t\t.cat(\" \".text())\n\t\t\t.cat(value.expression_document())\n\n\nprivate string_literal_wrap_char_limit: Int = 80\n\nprivate string_literal_wrap_min_search_width: Int = 48\n\n\nprivate pure func char_is_safe_plain_string_literal_char(c: Char) -> Bool:\n\tcode: Int = c.to_int()\n\tcode >= 32 and code < 127 and code != 34 and code != 36 and code != 92\n\n\nprivate pure func string_is_safe_to_wrap_as_plain_literal(value: String) -> Bool:\n\tvar safe: Bool = True\n\tvar i: Int = 0\n\n\twhile i < value.length():\n\t\tmatch value.get(i):\n\t\t\tSome(c):\n\t\t\t\tif not c.char_is_safe_plain_string_literal_char():\n\t\t\t\t\tsafe = False\n\t\t\t\t\tbreak\n\t\t\tNone:\n\t\t\t\tsafe = False\n\t\t\t\tbreak\n\n\t\ti += 1\n\n\tsafe\n\n\nprivate pure func char_is_string_literal_wrap_boundary(c: Char) -> Bool:\n\tcode: Int = c.to_int()\n\tcode == 32 or code == 44 or code == 45 or code == 46 or code == 47 or code == 58 or code == 59\n\n\nprivate pure func string_literal_wrap_end(value: String, start: Int) -> Int:\n\tlimit: Int = string_literal_wrap_char_limit\n\tremaining: Int = value.length() - start\n\n\tif remaining <= limit:\n\t\tvalue.length()\n\telse:\n\t\tfallback: Int = start + limit\n\t\tmin_end: Int = start + string_literal_wrap_min_search_width\n\t\tvar i: Int = fallback - 1\n\t\tvar found: Bool = False\n\t\tvar split_at: Int = fallback\n\n\t\twhile i >= min_end and not found:\n\t\t\tmatch value.get(i):\n\t\t\t\tSome(c):\n\t\t\t\t\tif c.char_is_string_literal_wrap_boundary():\n\t\t\t\t\t\tsplit_at = i + 1\n\t\t\t\t\t\tfound = True\n\t\t\t\tNone:\n\t\t\t\t\tvoid\n\n\t\t\ti -= 1\n\n\t\tsplit_at\n\n\nprivate pure func string_literal_wrap_chunks(value: String) -> List[String]:\n\tvar chunks: List[String] = []\n\tvar start: Int = 0\n\n\twhile start < value.length():\n\t\tend_idx: Int = value.string_literal_wrap_end(start)\n\t\tchunks = chunks.append(value.substring(start, end_idx - start))\n\t\tstart = end_idx\n\n\tchunks\n\n\nprivate pure func string_literal_can_wrap(value: String) -> Bool:\n\t(\n\t\tvalue.length() > string_literal_wrap_char_limit\n\t\tand value.string_is_safe_to_wrap_as_plain_literal()\n\t)\n\n\nprivate pure func plain_string_literal_document(value: String) -> Doc:\n\t(\"\\\"\" + value.escape_string_value() + \"\\\"\").text()\n\n\nprivate pure func wrapped_string_literal_chunk_documents(chunks: List[String]) -> List[Doc]:\n\tvar documents: List[Doc] = []\n\tvar index: Int = 0\n\n\tfor chunk in chunks:\n\t\tchunk_document: Doc = chunk.plain_string_literal_document()\n\n\t\tif index == 0:\n\t\t\tdocuments = documents.append(chunk_document)\n\t\telse:\n\t\t\tdocuments = documents.append(\n\t\t\t\t\"+ \"\n\t\t\t\t\t.text()\n\t\t\t\t\t.cat(chunk_document),\n\t\t\t)\n\n\t\tindex += 1\n\n\tdocuments\n\n\nprivate pure func wrapped_plain_string_literal_chunks_document(chunks: List[String]) -> Doc:\n\t\"(\"\n\t\t.text()\n\t\t.cat(\n\t\t\thardline\n\t\t\t\t.cat(\n\t\t\t\t\tchunks\n\t\t\t\t\t\t.wrapped_string_literal_chunk_documents()\n\t\t\t\t\t\t.hardlines(),\n\t\t\t\t)\n\t\t\t\t.indent(),\n\t\t)\n\t\t.cat(hardline)\n\t\t.cat(\")\".text())\n\n\nprivate pure func wrapped_plain_string_literal_document(value: String) -> Doc:\n\tvalue\n\t\t.string_literal_wrap_chunks()\n\t\t.wrapped_plain_string_literal_chunks_document()\n\n\nprivate pure func plain_string_literal_value(expr: Expression) -> Option[String]:\n\tmatch expr:\n\t\tLiteralExpression(StringLiteral(value, flags)):\n\t\t\tif (\n\t\t\t\tflags.raw\n\t\t\t\tor flags.multiline\n\t\t\t\tor not value.string_is_safe_to_wrap_as_plain_literal()\n\t\t\t):\n\t\t\t\tNone\n\t\t\telse:\n\t\t\t\tSome(value)\n\t\t_:\n\t\t\tNone\n\n\nprivate pure func plain_string_concat_chunks(expr: Expression) -> Option[List[String]]:\n\tmatch expr:\n\t\tBinaryExpression(AddOp, left, right):\n\t\t\tmatch left.plain_string_concat_chunks():\n\t\t\t\tSome(left_chunks):\n\t\t\t\t\tmatch right.plain_string_concat_chunks():\n\t\t\t\t\t\tSome(right_chunks):\n\t\t\t\t\t\t\tSome(left_chunks.concat(right_chunks))\n\t\t\t\t\t\tNone:\n\t\t\t\t\t\t\tNone\n\t\t\t\tNone:\n\t\t\t\t\tNone\n\t\t_:\n\t\t\tmatch expr.plain_string_literal_value():\n\t\t\t\tSome(value):\n\t\t\t\t\tSome([value])\n\t\t\t\tNone:\n\t\t\t\t\tNone\n\n\nprivate pure func concat_string_chunks(chunks: List[String]) -> String:\n\tvar result: String = \"\"\n\n\tfor chunk in chunks:\n\t\tresult += chunk\n\n\tresult\n\n\nprivate pure func string_concat_wrap_document(expr: Expression) -> Option[Doc]:\n\tmatch expr.plain_string_concat_chunks():\n\t\tSome(chunks):\n\t\t\tvalue: String = chunks.concat_string_chunks()\n\n\t\t\tif chunks.length() > 1 and value.string_literal_can_wrap():\n\t\t\t\tSome(value.wrapped_plain_string_literal_document())\n\t\t\telse:\n\t\t\t\tNone\n\t\tNone:\n\t\t\tNone\n\n\nprivate pure func unary_op_from_json(value: String) -> Result[UnaryOp, String]:\n\tmatch value:\n\t\t\"Neg\":\n\t\t\tOk(NegOp)\n\t\t\"Not\":\n\t\t\tOk(NotOp)\n\t\t_:\n\t\t\tErr(\"unknown unary operator: \" + value)\n\n\nprivate pure func binary_op_from_json(value: String) -> Result[BinaryOp, String]:\n\tmatch value:\n\t\t\"Add\":\n\t\t\tOk(AddOp)\n\t\t\"Sub\":\n\t\t\tOk(SubOp)\n\t\t\"Mul\":\n\t\t\tOk(MulOp)\n\t\t\"Div\":\n\t\t\tOk(DivOp)\n\t\t\"Mod\":\n\t\t\tOk(ModOp)\n\t\t\"Lt\":\n\t\t\tOk(LtOp)\n\t\t\"Gt\":\n\t\t\tOk(GtOp)\n\t\t\"Le\":\n\t\t\tOk(LeOp)\n\t\t\"Ge\":\n\t\t\tOk(GeOp)\n\t\t\"Eq\":\n\t\t\tOk(EqOp)\n\t\t\"Ne\":\n\t\t\tOk(NeOp)\n\t\t_:\n\t\t\tErr(\"unknown binary operator: \" + value)\n\n\nprivate pure func logical_op_from_json(value: String) -> Result[LogicalOp, String]:\n\tmatch value:\n\t\t\"And\":\n\t\t\tOk(AndOp)\n\t\t\"Or\":\n\t\t\tOk(OrOp)\n\t\t_:\n\t\t\tErr(\"unknown logical operator: \" + value)\n\n\nprivate pure func unary_text(op: UnaryOp) -> String:\n\tmatch op:\n\t\tNegOp:\n\t\t\t\"-\"\n\t\tNotOp:\n\t\t\t\"not \"\n\n\nprivate pure func binary_text(op: BinaryOp) -> String:\n\tmatch op:\n\t\tAddOp:\n\t\t\t\"+\"\n\t\tSubOp:\n\t\t\t\"-\"\n\t\tMulOp:\n\t\t\t\"*\"\n\t\tDivOp:\n\t\t\t\"/\"\n\t\tModOp:\n\t\t\t\"%\"\n\t\tLtOp:\n\t\t\t\"<\"\n\t\tGtOp:\n\t\t\t\">\"\n\t\tLeOp:\n\t\t\t\"<=\"\n\t\tGeOp:\n\t\t\t\">=\"\n\t\tEqOp:\n\t\t\t\"==\"\n\t\tNeOp:\n\t\t\t\"!=\"\n\n\nprivate pure func logical_text(op: LogicalOp) -> String:\n\tmatch op:\n\t\tAndOp:\n\t\t\t\"and\"\n\t\tOrOp:\n\t\t\t\"or\"\n\n\nprivate pure func binary_prec(op: BinaryOp) -> Int:\n\tmatch op:\n\t\tMulOp:\n\t\t\t7\n\t\tDivOp:\n\t\t\t7\n\t\tModOp:\n\t\t\t7\n\t\tAddOp:\n\t\t\t6\n\t\tSubOp:\n\t\t\t6\n\t\t_:\n\t\t\t4\n\n\nprivate pure func logical_prec(op: LogicalOp) -> Int:\n\tmatch op:\n\t\tAndOp:\n\t\t\t2\n\t\tOrOp:\n\t\t\t1\n\n\nprivate pure func expression_precedence(expr: Expression) -> Int:\n\tmatch expr:\n\t\tAscriptionExpression(_, _):\n\t\t\t0\n\t\tBinaryExpression(op, _, _):\n\t\t\top.binary_prec()\n\t\tLogicalExpression(op, _, _):\n\t\t\top.logical_prec()\n\t\t_:\n\t\t\t100\n\n\nprivate pure func needs_field_receiver_parens(expr: Expression) -> Bool:\n\tmatch expr:\