  ("tools/formatter/formatter.brp", "import:\n\t./command_line:\n\t\tParsedCommand(CommandMessage, CommandProgram, CommandProgramBatch),\n\t\tProgramArgs,\n\t\tProgramBatchArgs,\n\t\thelp_text,\n\t\tis_help_arg,\n\t\tparse_command,\n\t./formatter_commands: render_program_json_file, write_rendered_program_json\n\n\nfunc render_program_command(parsed: ProgramArgs) -> Result[String, String]:\n\tparsed.path.render_program_json_file(parsed.width)\n\n\nfunc run_program_batch_command(parsed: ProgramBatchArgs) -> Result[Bool, String]:\n\tvar error: Option[String] = None\n\n\tfor pair in parsed.pairs:\n\t\tmatch error:\n\t\t\tSome(_):\n\t\t\t\tvoid\n\t\t\tNone:\n\t\t\t\tmatch write_rendered_program_json(pair[0], pair[1], parsed.width):\n\t\t\t\t\tErr(msg):\n\t\t\t\t\t\terror = Some(msg)\n\t\t\t\t\tOk(_):\n\t\t\t\t\t\tvoid\n\n\tmatch error:\n\t\tSome(msg):\n\t\t\tErr(msg)\n\t\tNone:\n\t\t\tOk(True)\n\n\nfunc print_render_result(result: Result[String, String]) -> Int:\n\tmatch result:\n\t\tErr(msg):\n\t\t\tprint(msg)\n\t\t\t1\n\t\tOk(rendered):\n\t\t\tputs(rendered)\n\t\t\t0\n\n\nfunc print_check_result(result: Result[Bool, String]) -> Int:\n\tmatch result:\n\t\tErr(msg):\n\t\t\tprint(msg)\n\t\t\t1\n\t\tOk(_):\n\t\t\t0\n\n\nfunc run_parsed_command(parsed: ParsedCommand) -> Int:\n\tmatch parsed:\n\t\tCommandMessage(message, status):\n\t\t\tprint(message)\n\t\t\tstatus\n\t\tCommandProgram(args):\n\t\t\tprint_render_result(args.render_program_command())\n\t\tCommandProgramBatch(args):\n\t\t\tprint_check_result(args.run_program_batch_command())\n\n\nfunc main(args: List[String]) -> Int:\n\tuser_args: List[String] = args.drop(1)\n\n\tmatch user_args.get(0):\n\t\tSome(command):\n\t\t\tif command.is_help_arg():\n\t\t\t\tprint(help_text)\n\t\t\t\t0\n\t\t\telse:\n\t\t\t\tcommand\n\t\t\t\t\t.parse_command(user_args.drop(1))\n\t\t\t\t\t.run_parsed_command()\n\t\tNone:\n\t\t\tprint(help_text)\n\t\t\t1\n");
  ("tools/formatter/formatter_commands.brp", "import:\n\t./declaration_documents: render_program_json\n\tsystem: file_exists, read_file, write_file\n\n\nfunc render_program_json_file(path: String, width: Int) -> Result[String, String]:\n\tif not path.file_exists():\n\t\tErr(\"program JSON file not found: \" + path)\n\telse:\n\t\tmatch path.read_file():\n\t\t\tErr(msg):\n\t\t\t\tErr(\"failed to read program JSON: \" + msg)\n\t\t\tOk(json):\n\t\t\t\twidth.render_program_json(json)\n\n\nfunc write_rendered_program_json(\n\tinput_path: String,\n\toutput_path: String,\n\twidth: Int,\n) -> Result[Void, String]:\n\tmatch input_path.render_program_json_file(width):\n\t\tErr(msg):\n\t\t\tErr(msg)\n\t\tOk(rendered):\n\t\t\toutput_path.write_file(rendered)\n");
  ("tools/formatter/json_fields.brp", "import:\n\tjson: JsonValue\n\n\npure func missing_field(key: String) -> String:\n\t\"missing formatter JSON field: \" + key\n\n\npure func expected_field(key: String, expected: String) -> String:\n\t\"expected formatter JSON field '\" + key + \"' to be \" + expected\n\n\npure func field(value: JsonValue, key: String) -> Result[JsonValue, String]:\n\tmatch value.get_field(key):\n\t\tSome(child):\n\t\t\tOk(child)\n\t\tNone:\n\t\t\tErr(missing_field(key))\n\n\npure func string_field(value: JsonValue, key: String) -> Result[String, String]:\n\tchild ?= value.field(key)\n\n\tmatch child.as_string():\n\t\tSome(s):\n\t\t\tOk(s)\n\t\tNone:\n\t\t\tErr(expected_field(key, \"a string\"))\n\n\npure func int_field(value: JsonValue, key: String) -> Result[Int, String]:\n\tchild ?= value.field(key)\n\n\tmatch child.as_number():\n\t\tSome(n):\n\t\t\tOk(to_int(n))\n\t\tNone:\n\t\t\tErr(expected_field(key, \"a number\"))\n\n\npure func bool_field(value: JsonValue, key: String) -> Result[Bool, String]:\n\tchild ?= value.field(key)\n\n\tmatch child.as_bool():\n\t\tSome(b):\n\t\t\tOk(b)\n\t\tNone:\n\t\t\tErr(expected_field(key, \"a boolean\"))\n\n\npure func array_field(value: JsonValue, key: String) -> Result[List[JsonValue], String]:\n\tchild ?= value.field(key)\n\n\tmatch child.as_array():\n\t\tSome(items):\n\t\t\tOk(items)\n\t\tNone:\n\t\t\tErr(expected_field(key, \"an array\"))\n\n\npure func parsed_array_items[T](\n\titems: List[JsonValue],\n\tparse_item: pure (JsonValue) -> Result[T, String],\n) -> Result[List[T], String]:\n\tvar result: List[T] = []\n\tvar error: Option[String] = None\n\n\tfor item in items:\n\t\tmatch error:\n\t\t\tSome(_):\n\t\t\t\tvoid\n\t\t\tNone:\n\t\t\t\tmatch parse_item(item):\n\t\t\t\t\tOk(parsed):\n\t\t\t\t\t\tresult = result.append(parsed)\n\t\t\t\t\tErr(msg):\n\t\t\t\t\t\terror = Some(msg)\n\n\tmatch error:\n\t\tSome(msg):\n\t\t\tErr(msg)\n\t\tNone:\n\t\t\tOk(result)\n\n\npure func parsed_array_field[T](\n\tvalue: JsonValue,\n\tkey: String,\n\tparse_item: pure (JsonValue) -> Result[T, String],\n) -> Result[List[T], String]:\n\titems ?= value.array_field(key)\n\titems.parsed_array_items(parse_item)\n");
  ("tools/formatter/type_documents.brp", "import:\n\t./document_layout: Doc, comma_sep, layout, text\n\t./json_fields: bool_field, field, int_field, parsed_array_field, string_field\n\tjson: JsonValue, parse_json\n\n\nunion TypeDimensionOperator:\n\tTypeDimensionAdd\n\tTypeDimensionSub\n\tTypeDimensionMul\n\tTypeDimensionDiv\n\n\nunion TypeExpression:\n\tNamedType(String, List[TypeExpression])\n\tArrayType(TypeExpression, List[TypeExpression])\n\tFuncType(Bool, List[TypeExpression], TypeExpression)\n\tVarType(String)\n\tBoundVarType(String)\n\tConstIntType(Int)\n\tTupleType(List[TypeExpression])\n\tSelfType\n\tVarDimsType(String)\n\tRangeType(TypeExpression)\n\tDimensionOperationType(TypeDimensionOperator, TypeExpression, TypeExpression)\n\tMetaType(Int)\n\n\nrecord TypeConstraint {\n\tleft: TypeExpression,\n\tright: TypeExpression\n}\n\n\nprivate pure func type_expression_list_contains_function(types: List[TypeExpression]) -> Bool:\n\tvar contains: Bool = False\n\n\tfor type_expression in types:\n\t\tif type_expression.type_expression_contains_function():\n\t\t\tcontains = True\n\t\t\tbreak\n\n\tcontains\n\n\npure func type_expression_contains_function(type_expression: TypeExpression) -> Bool:\n\tmatch type_expression:\n\t\tFuncType(_, _, _):\n\t\t\tTrue\n\t\tNamedType(_, args):\n\t\t\targs.type_expression_list_contains_function()\n\t\tArrayType(elem, dims):\n\t\t\t(\n\t\t\t\telem.type_expression_contains_function()\n\t\t\t\tor dims.type_expression_list_contains_function()\n\t\t\t)\n\t\tTupleType(elems):\n\t\t\telems.type_expression_list_contains_function()\n\t\tRangeType(inner):\n\t\t\tinner.type_expression_contains_function()\n\t\tDimensionOperationType(_, left, right):\n\t\t\tleft.type_expression_contains_function() or right.type_expression_contains_function()\n\t\t_:\n\t\t\tFalse\n\n\nprivate pure func dimension_operator_from_json(\n\tvalue: String,\n) -> Result[TypeDimensionOperator, String]:\n\tmatch value:\n\t\t\"Add\":\n\t\t\tOk(TypeDimensionAdd)\n\t\t\"Sub\":\n\t\t\tOk(TypeDimensionSub)\n\t\t\"Mul\":\n\t\t\tOk(TypeDimensionMul)\n\t\t\"Div\":\n\t\t\tOk(TypeDimensionDiv)\n\t\t_:\n\t\t\tErr(\"unknown type dimension operator: \" + value)\n\n\nprivate pure func is_additive_dimension_expression(type_expression: TypeExpression) -> Bool:\n\tmatch type_expression:\n\t\tDimensionOperationType(TypeDimensionAdd, _, _):\n\t\t\tTrue\n\t\tDimensionOperationType(TypeDimensionSub, _, _):\n\t\t\tTrue\n\t\t_:\n\t\t\tFalse\n\n\nprivate pure func type_expression_field(\n\tvalue: JsonValue,\n\tkey: String,\n) -> Result[TypeExpression, String]:\n\tchild ?= value.field(key)\n\tchild.type_expression_from_json()\n\n\nprivate pure func type_expression_array_field(\n\tvalue: JsonValue,\n\tkey: String,\n) -> Result[List[TypeExpression], String]:\n\tvalue.parsed_array_field(key, type_expression_from_json)\n\n\npure func type_expression_from_json(value: JsonValue) -> Result[TypeExpression, String]:\n\ttag ?= value.string_field(\"tag\")\n\n\tmatch tag:\n\t\t\"Named\":\n\t\t\tname ?= value.string_field(\"name\")\n\t\t\targs ?= value.type_expression_array_field(\"args\")\n\t\t\tOk(NamedType(name, args))\n\t\t\"Array\":\n\t\t\telem ?= value.type_expression_field(\"elem\")\n\t\t\tdims ?= value.type_expression_array_field(\"dims\")\n\t\t\tOk(ArrayType(elem, dims))\n\t\t\"Func\":\n\t\t\tis_pure ?= value.bool_field(\"pure\")\n\t\t\tparams ?= value.type_expression_array_field(\"params\")\n\t\t\treturn_ty ?= value.type_expression_field(\"return\")\n\t\t\tOk(FuncType(is_pure, params, return_ty))\n\t\t\"Var\":\n\t\t\tname ?= value.string_field(\"name\")\n\t\t\tOk(VarType(name))\n\t\t\"BoundVar\":\n\t\t\tsource ?= value.string_field(\"source\")\n\t\t\tOk(BoundVarType(source))\n\t\t\"ConstInt\":\n\t\t\tvalue_int ?= value.int_field(\"value\")\n\t\t\tOk(ConstIntType(value_int))\n\t\t\"Tuple\":\n\t\t\telems ?= value.type_expression_array_field(\"elems\")\n\t\t\tOk(TupleType(elems))\n\t\t\"Self\":\n\t\t\tOk(SelfType)\n\t\t\"VarDims\":\n\t\t\tname ?= value.string_field(\"name\")\n\t\t\tOk(VarDimsType(name))\n\t\t\"Range\":\n\t\t\tinner ?= value.type_expression_field(\"inner\")\n\t\t\tOk(RangeType(inner))\n\t\t\"DimOp\":\n\t\t\traw_op ?= value.string_field(\"op\")\n\t\t\top ?= raw_op.dimension_operator_from_json()\n\t\t\tleft ?= value.type_expression_field(\"left\")\n\t\t\tright ?= value.type_expression_field(\"right\")\n\t\t\tOk(DimensionOperationType(op, left, right))\n\t\t\"Meta\":\n\t\t\tid ?= value.int_field(\"id\")\n\t\t\tOk(MetaType(id))\n\t\t_:\n\t\t\tErr(\"unknown type expression JSON tag: \" + tag)\n\n\npure func type_expression_from_json_string(input: String) -> Result[TypeExpression, String]:\n\tvalue ?= input.parse_json()\n\tvalue.type_expression_from_json()\n\n\npure func type_constraint_from_json(value: JsonValue) -> Result[TypeConstraint, String]:\n\tleft ?= value.type_expression_field(\"left\")\n\tright ?= value.type_expression_field(\"right\")\n\tOk({\n\t\tleft = left,\n\t\tright = right,\n\t})\n\n\npure func type_constraint_array_field(\n\tvalue: JsonValue,\n\tkey: String,\n) -> Result[List[TypeConstraint], String]:\n\tvalue.parsed_array_field(key, type_constraint_from_json)\n\n\npure func type_constraint_array_field_or_empty(\n\tvalue: JsonValue,\n\tkey: String,\n) -> Result[List[TypeConstraint], String]:\n\tmatch value.get_field(key):\n\t\tNone:\n\t\t\tOk([])\n\t\tSome(_):\n\t\t\tvalue.type_constraint_array_field(key)\n\n\nprivate pure func type_document_list(types: List[TypeExpression]) -> List[Doc]:\n\tvar documents: List[Doc] = []\n\n\tfor type_expression in types:\n\t\tdocuments = documents.append(type_expression.type_document())\n\n\tdocuments\n\n\nprivate pure func array_element_type_document(type_expression: TypeExpression) -> Doc:\n\tmatch type_expression:\n\t\tFuncType(_, _, _):\n\t\t\ttype_expression\n\t\t\t\t.type_document()\n\t\t\t\t.parens()\n\t\t_:\n\t\t\ttype_expression.type_document()\n\n\nprivate pure func dimension_operand_document(type_expression: TypeExpression) -> Doc:\n\tif type_expression.is_additive_dimension_expression():\n\t\ttype_expression\n\t\t\t.type_document()\n\t\t\t.parens()\n\telse:\n\t\ttype_expression.type_document()\n\n\npure func type_document(type_expression: TypeExpression) -> Doc:\n\tmatch type_expression:\n\t\tNamedType(name, args):\n\t\t\tif args.length() == 0:\n\t\t\t\tname.text()\n\t\t\telse:\n\t\t\t\tname\n\t\t\t\t\t.text()\n\t\t\t\t\t.cat(\"[\".text())\n\t\t\t\t\t.cat(\n\t\t\t\t\t\targs\n\t\t\t\t\t\t\t.type_document_list()\n\t\t\t\t\t\t\t.comma_sep(),\n\t\t\t\t\t)\n\t\t\t\t\t.cat(\"]\".text())\n\t\tArrayType(elem, dims):\n\t\t\telem\n\t\t\t\t.array_element_type_document()\n\t\t\t\t.cat(\"[\".text())\n\t\t\t\t.cat(\n\t\t\t\t\tdims\n\t\t\t\t\t\t.type_document_list()\n\t\t\t\t\t\t.comma_sep(),\n\t\t\t\t)\n\t\t\t\t.cat(\"]\".text())\n\t\tFuncType(is_pure, params, return_ty):\n\t\t\tprefix: Doc = if is_pure:\n\t\t\t\t\"pure \".text()\n\t\t\telse:\n\t\t\t\t\"\".text()\n\n\t\t\tprefix\n\t\t\t\t.cat(\"(\".text())\n\t\t\t\t.cat(\n\t\t\t\t\tparams\n\t\t\t\t\t\t.type_document_list()\n\t\t\t\t\t\t.comma_sep(),\n\t\t\t\t)\n\t\t\t\t.cat(\") -> \".text())\n\t\t\t\t.cat(return_ty.type_document())\n\t\tVarType(name):\n\t\t\tname.text()\n\t\tBoundVarType(source):\n\t\t\tsource.text()\n\t\tConstIntType(value):\n\t\t\t(\"#\" + value.to_string()).text()\n\t\tTupleType(elems):\n\t\t\t\"(\"\n\t\t\t\t.text()\n\t\t\t\t.cat(\n\t\t\t\t\telems\n\t\t\t\t\t\t.type_document_list()\n\t\t\t\t\t\t.comma_sep(),\n\t\t\t\t)\n\t\t\t\t.cat(\")\".text())\n\t\tSelfType:\n\t\t\t\"Self\".text()\n\t\tVarDimsType(name):\n\t\t\t(name + \"...\").text()\n\t\tRangeType(inner):\n\t\t\t\"..\"\n\t\t\t\t.text()\n\t\t\t\t.cat(inner.type_document())\n\t\tDimensionOperationType(op, left, right):\n\t\t\tmatch op:\n\t\t\t\tTypeDimensionAdd:\n\t\t\t\t\tleft\n\t\t\t\t\t\t.type_document()\n\t\t\t\t\t\t.cat(\" + \".text())\n\t\t\t\t\t\t.cat(right.type_document())\n\t\t\t\tTypeDimensionSub:\n\t\t\t\t\tleft\n\t\t\t\t\t\t.type_document()\n\t\t\t\t\t\t.cat(\" - \".text())\n\t\t\t\t\t\t.cat(right.type_document())\n\t\t\t\tTypeDimensionMul:\n\t\t\t\t\tleft\n\t\t\t\t\t\t.dimension_operand_document()\n\t\t\t\t\t\t.cat(\" * \".text())\n\t\t\t\t\t\t.cat(right.dimension_operand_document())\n\t\t\t\tTypeDimensionDiv:\n\t\t\t\t\tleft\n\t\t\t\t\t\t.dimension_operand_document()\n\t\t\t\t\t\t.cat(\" / \".text())\n\t\t\t\t\t\t.cat(right.dimension_operand_document())\n\t\tMetaType(id):\n\t\t\t(\"?m\" + id.to_string()).text()\n\n\npure func type_constraint_document(constraint: TypeConstraint) -> Doc:\n\tconstraint.left\n\t\t.type_document()\n\t\t.cat(\" == \".text())\n\t\t.cat(constraint.right.type_document())\n\n\npure func type_constraint_documents(constraints: List[TypeConstraint]) -> List[Doc]:\n\tvar documents: List[Doc] = []\n\n\tfor constraint in constraints:\n\t\tdocuments = documents.append(constraint.type_constraint_document())\n\n\tdocuments\n\n\npure func render_type_json(width: Int, input: String) -> Result[String, String]:\n\ttype_expression ?= input.type_expression_from_json_string()\n\tOk(width.layout(type_expression.type_document()))\n");
]

let find path = List.assoc_opt path files
